content:
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --bg-page: #f8fafc;
  --bg-surface: #ffffff;
  --bg-hover: #f1f5f9;
  --bg-subtle: #f8fafc;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --badge-bg: #e2e8f0;
  --badge-text: #334155;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 860px;
  margin: 0 auto;
  padding: 2.5rem 1rem;
  min-height: 100vh;
}

.header-section {
  text-align: center;
  margin-bottom: 2rem;
}

.app-title {
  font-size: 1.875rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.025em;
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 0.5rem;
}

.control-panel {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
}

.search-box-wrapper {
  position: relative;
  flex: 1;
  min-width: 240px;
  display: flex;
  align-items: center;
}

.search-input {
  width: 100%;
  padding: 0.65rem 2.25rem 0.65rem 0.95rem;
  font-size: 0.925rem;
  color: var(--text-main);
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.search-input::placeholder {
  color: #94a3b8;
}

.search-input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.search-clear-btn {
  position: absolute;
  right: 0.6rem;
  background: transparent;
  border: none;
  color: #94a3b8;
  cursor: pointer;
  padding: 0.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 0.85rem;
  transition: color 0.15s ease, background-color 0.15s ease;
}

.search-clear-btn:hover {
  color: var(--text-main);
  background-color: #e2e8f0;
}

.count-badge {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--badge-text);
  background-color: var(--badge-bg);
  padding: 0.4rem 0.85rem;
  border-radius: 9999px;
  white-space: nowrap;
}

.table-wrapper {
  background-color: var(--bg-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-md);
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.employee-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

.table-header-cell {
  padding: 0.9rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  background-color: var(--bg-subtle);
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.15s ease, color 0.15s ease;
  white-space: nowrap;
}

.table-header-cell:hover {
  background-color: var(--bg-hover);
  color: var(--text-main);
}

.sort-indicator {
  display: inline-flex;
  align-items: center;
  margin-left: 0.4rem;
  font-size: 0.8rem;
  color: var(--primary-color);
  vertical-align: middle;
}

.table-row {
  transition: background-color 0.15s ease;
}

.table-row:not(:last-child) .table-cell {
  border-bottom: 1px solid var(--border-color);
}

.table-row:hover {
  background-color: var(--bg-hover);
}

.table-cell {
  padding: 1rem 1.25rem;
  font-size: 0.925rem;
  color: var(--text-main);
  white-space: nowrap;
}

.empty-state {
  padding: 4rem 1.5rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.empty-message {
  font-size: 1rem;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}

.reset-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.55rem 1.15rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: #ffffff;
  background-color: var(--primary-color);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

.reset-btn:hover {
  background-color: var(--primary-hover);
}

.reset-btn:active {
  transform: translateY(1px);
}

@media (max-width: 640px) {
  .app-container {
    padding: 1.5rem 0.75rem;
  }

  .app-title {
    font-size: 1.5rem;
  }

  .control-panel {
    flex-direction: column;
    align-items: stretch;
  }

  .count-badge {
    text-align: center;
  }

  .table-header-cell,
  .table-cell {
    padding: 0.75rem 0.9rem;
    font-size: 0.85rem;
  }
}

export interface Employee {
  id: number;
  name: string;
  department: string;
  age: number;
}

export type SortKey = 'name' | 'department' | 'age';

export type SortOrder = 'asc' | 'desc';

export interface SortConfig {
  key: SortKey;
  order: SortOrder;
}

import { Employee } from './types';

export const initialEmployees: Employee[] = [
  { id: 1, name: '佐藤 健一', department: '開発部', age: 28 },
  { id: 2, name: '鈴木 美咲', department: '営業部', age: 25 },
  { id: 3, name: '高橋 陽介', department: 'マーケティング部', age: 34 },
  { id: 4, name: '田中 裕子', department: '人事部', age: 41 },
  { id: 5, name: '伊藤 大輝', department: '開発部', age: 31 },
  { id: 6, name: '渡辺 彩花', department: '総務部', age: 27 },
  { id: 7, name: '山本 拓也', department: '営業部', age: 45 },
  { id: 8, name: '中村 結衣', department: 'マーケティング部', age: 24 },
  { id: 9, name: '小林 誠', department: '開発部', age: 38 },
  { id: 10, name: '加藤 恵美', department: '人事部', age: 32 }
];

export const employees: Employee[] = initialEmployees;

import { ChangeEvent } from 'react';

interface SearchBarProps {
  searchTerm: string;
  onSearchChange: (value: string) => void;
  totalCount: number;
  filteredCount: number;
}

const SearchBar = ({
  searchTerm = '',
  onSearchChange,
  totalCount = 0,
  filteredCount = 0
}: SearchBarProps) => {
  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    onSearchChange?.(e.target.value);
  };

  const handleClear = () => {
    onSearchChange?.('');
  };

  return (
    <div className="control-panel">
      <div className="search-box-wrapper">
        <input
          type="text"
          className="search-input"
          placeholder="社員名で検索..."
          value={searchTerm}
          onChange={handleChange}
          aria-label="社員名で検索"
        />
        {searchTerm !== '' && (
          <button
            type="button"
            className="search-clear-btn"
            onClick={handleClear}
            title="検索語をクリア"
            aria-label="検索語をクリア"
          >
            ✕
          </button>
        )}
      </div>
      <div className="count-badge">
        表示中: {filteredCount} / {totalCount} 名
      </div>
    </div>
  );
};

export default SearchBar;

import { Employee, SortConfig, SortKey } from '../types';

interface EmployeeTableProps {
  employees?: Employee[];
  sortConfig: SortConfig;
  onSort?: (key: SortKey) => void;
  onResetFilter?: () => void;
}

interface ColumnHeader {
  key: SortKey;
  label: string;
}

const columns: ColumnHeader[] = [
  { key: 'name', label: '氏名' },
  { key: 'department', label: '部署' },
  { key: 'age', label: '年齢' }
];

const EmployeeTable = ({
  employees = [],
  sortConfig,
  onSort,
  onResetFilter
}: EmployeeTableProps) => {
  const renderSortIndicator = (columnKey: SortKey) => {
    if (sortConfig.key !== columnKey) {
      return null;
    }
    return (
      <span className="sort-indicator" aria-hidden="true">
        {sortConfig.order === 'asc' ? '▲' : '▼'}
      </span>
    );
  };

  if (employees.length === 0) {
    return (
      <div className="table-wrapper">
        <div className="empty-state">
          <p className="empty-message">条件に一致する社員が見つかりませんでした。</p>
          <button
            type="button"
            className="reset-btn"
            onClick={() => onResetFilter?.()}
          >
            検索条件をクリア
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="table-wrapper">
      <table className="employee-table">
        <thead>
          <tr>
            {columns.map((column) => (
              <th
                key={column.key}
                className="table-header-cell"
                onClick={() => onSort?.(column.key)}
                tabIndex={0}
                role="button"
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    onSort?.(column.key);
                  }
                }}
                aria-label={`${column.label}でソート`}
              >
                {column.label}
                {renderSortIndicator(column.key)}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {employees.map((employee) => (
            <tr key={employee.id} className="table-row">
              <td className="table-cell">{employee.name}</td>
              <td className="table-cell">{employee.department}</td>
              <td className="table-cell">{employee.age} 歳</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default EmployeeTable;

import { useState, useMemo } from 'react';
import { initialEmployees } from './data';
import { Employee, SortConfig, SortKey } from './types';
import SearchBar from './components/SearchBar';
import EmployeeTable from './components/EmployeeTable';

const App = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({
    key: 'name',
    order: 'asc'
  });

  const handleSort = (key: SortKey) => {
    setSortConfig((prev) => {
      if (prev.key === key) {
        return {
          key,
          order: prev.order === 'asc' ? 'desc' : 'asc'
        };
      }
      return {
        key,
        order: 'asc'
      };
    });
  };

  const handleResetFilter = () => {
    setSearchTerm('');
  };

  const filteredAndSortedEmployees = useMemo(() => {
    const trimmed = searchTerm.trim().toLowerCase();

    const filtered = initialEmployees.filter((employee: Employee) => {
      if (!trimmed) return true;
      return employee.name.toLowerCase().includes(trimmed);
    });

    const sorted = [...filtered].sort((a: Employee, b: Employee) => {
      const aValue = a[sortConfig.key];
      const bValue = b[sortConfig.key];

      if (typeof aValue === 'number' && typeof bValue === 'number') {
        return sortConfig.order === 'asc' ? aValue - bValue : bValue - aValue;
      }

      const aString = String(aValue);
      const bString = String(bValue);

      const comparison = aString.localeCompare(bString, 'ja');
      return sortConfig.order === 'asc' ? comparison : -comparison;
    });

    return sorted;
  }, [searchTerm, sortConfig]);

  return (
    <main className="app-container">
      <header className="header-section">
        <h1 className="app-title">社員名簿一覧</h1>
        <p className="app-subtitle">社員の検索および各項目による並び替えが可能です</p>
      </header>

      <SearchBar
        searchTerm={searchTerm}
        onSearchChange={setSearchTerm}
        totalCount={initialEmployees.length}
        filteredCount={filteredAndSortedEmployees.length}
      />

      <EmployeeTable
        employees={filteredAndSortedEmployees}
        sortConfig={sortConfig}
        onSort={handleSort}
        onResetFilter={handleResetFilter}
      />
    </main>
  );
};

export default App;
